<?php
require_once __DIR__.'/../includes/bootstrap.php';require_role('programme_officer');$user=current_user();$flashes=render_flashes();$currentPage='cohorts';$pageTitle='Cohorts';require_once __DIR__.'/_helpers.php';$conn=Database::getConnection();$officerId=(int)($user['id']??$user['user_id']??0);if($officerId<=0){http_response_code(403);exit('Invalid Programme Officer account.');}$scope=po_scope($conn,'p','c');$search=trim((string)($_GET['search']??''));$status=trim((string)($_GET['status']??''));$programmeId=(int)($_GET['programme_id']??0);$where=[$scope['condition']];$params=[$officerId];$types='i';if($search!==''){$where[]='(c.name LIKE ? OR p.name LIKE ?)';$like='%'.$search.'%';$params[]=$like;$params[]=$like;$types.='ss';}if($status!==''){$where[]='c.status = ?';$params[]=$status;$types.='s';}if($programmeId>0){$where[]='p.id = ?';$params[]=$programmeId;$types.='i';}$sql="SELECT c.id,c.name,c.status,c.start_date,c.end_date,p.id programme_id,p.name programme_name,COUNT(DISTINCT CASE WHEN cp.status<>'withdrawn' THEN cp.user_id END) candidate_count,COUNT(DISTINCT CASE WHEN cp.status='active' THEN cp.user_id END) active_count,COUNT(DISTINCT CASE WHEN cp.status='completed' THEN cp.user_id END) completed_count FROM cohorts c INNER JOIN programmes p ON p.id=c.programme_id LEFT JOIN cohort_participants cp ON cp.cohort_id=c.id WHERE ".implode(' AND ',$where)." GROUP BY c.id,c.name,c.status,c.start_date,c.end_date,p.id,p.name ORDER BY CASE WHEN c.status='active' THEN 0 ELSE 1 END,c.start_date DESC,c.id DESC";$rows=[];if($scope['mode']!=='none'){$stmt=$conn->prepare($sql);$stmt->bind_param($types,...$params);$stmt->execute();$r=$stmt->get_result();while($row=$r->fetch_assoc())$rows[]=$row;$stmt->close();}require __DIR__.'/_layout_start.php';?>
<div class="po-page-header"><div><span class="po-page-header__eyebrow">Programme Delivery</span><h2>Cohorts</h2><p>Monitor cohort timelines, participant totals and delivery progress across your programme portfolio.</p></div></div>
<form class="po-filter" method="get"><?php if($programmeId>0):?><input type="hidden" name="programme_id" value="<?= $programmeId ?>"><?php endif;?><div class="po-field po-field--grow"><label>Search</label><div class="po-input-icon"><i class="fas fa-magnifying-glass"></i><input name="search" value="<?= e($search) ?>" placeholder="Cohort or programme"></div></div><div class="po-field"><label>Status</label><select name="status"><option value="">All statuses</option><?php foreach(['active','completed','upcoming','inactive'] as $s):?><option value="<?= e($s) ?>" <?= $status===$s?'selected':'' ?>><?= e(po_status_label($s)) ?></option><?php endforeach;?></select></div><div class="po-filter__actions"><button class="po-btn po-btn--primary"><i class="fas fa-filter"></i> Apply</button><a class="po-btn po-btn--secondary" href="<?= url('programme_officer/cohorts.php') ?>">Reset</a></div></form>
<div class="po-card"><div class="po-card__header"><div><h3>Programme Cohorts</h3><p><?= number_format(count($rows)) ?> cohort(s) found.</p></div></div><?php if(!$rows):?><div class="po-empty"><div class="po-empty__icon"><i class="fas fa-layer-group"></i></div><strong>No cohorts found</strong><span>No cohort matched the current filters or Officer assignment.</span></div><?php else:?><div class="po-table-wrap"><table class="po-table"><thead><tr><th>Cohort</th><th>Status</th><th>Timeline</th><th>Candidates</th><th>Completion</th><th></th></tr></thead><tbody><?php foreach($rows as $c):$rate=po_completion_rate((int)$c['candidate_count'],(int)$c['completed_count']);?><tr><td><div class="po-table-title"><span class="po-table-title__icon"><i class="fas fa-layer-group"></i></span><div><strong><?= e($c['name']) ?></strong><span><?= e($c['programme_name']) ?></span></div></div></td><td><span class="po-status po-status--<?= e(po_status_class($c['status'])) ?>"><?= e(po_status_label($c['status'])) ?></span></td><td><strong><?= e(po_date($c['start_date'])) ?></strong><span class="po-table-sub">to <?= e(po_date($c['end_date'])) ?></span></td><td><?= number_format((int)$c['candidate_count']) ?><span class="po-table-sub"><?= number_format((int)$c['active_count']) ?> active</span></td><td><div class="po-progress po-progress--table"><div class="po-progress__labels"><span>Progress</span><strong><?= $rate ?>%</strong></div><div class="po-progress__track"><span style="width:<?= $rate ?>%"></span></div></div></td><td class="po-table__action"><a class="po-icon-btn" href="<?= url('programme_officer/cohort_view.php?id='.(int)$c['id']) ?>"><i class="fas fa-arrow-right"></i></a></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></div>
<?php require __DIR__.'/_layout_end.php';?>
